import jwt
from datetime import datetime
from rest_framework_jwt.settings import api_settings
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.contrib.auth import get_user_model
from .permissions import IsHelpdeskSuperAdmin

User = get_user_model()

def generate_impersonation_token_payload(operator_user, target_user):
    payload = {
        'user_id': target_user.id,
        'operator_id': operator_user.id,
        'is_impersonated': True,
        'exp': datetime.utcnow() + api_settings.JWT_EXPIRATION_DELTA
    }
    return payload

class SupportImpersonationTokenView(APIView):
    permission_classes = [permissions.IsAuthenticated, IsHelpdeskSuperAdmin]

    def post(self, request):
        target_user_id = request.data.get('target_user_id')
        try:
            target_user = User.objects.get(id=target_user_id, organization=request.user.organization, is_staff=False)
        except User.DoesNotExist:
            return Response({'detail': 'Target user not found or cannot be impersonated'}, status=status.HTTP_404_NOT_FOUND)

        payload = generate_impersonation_token_payload(request.user, target_user)
        jwt_encode_handler = api_settings.JWT_ENCODE_HANDLER
        token = jwt_encode_handler(payload)
        return Response({'token': token, 'target_user_id': target_user.id})
